#include <vector>

class Solution {
public:
    long long weightedSumOfTree(const std::vector<int>& vals) {
        int n = vals.size();
        if (n == 0) return 0;
        long long total = 0;
        auto dfs = [&](auto self, int idx, int depth) -> void {
            if (idx >= n || vals[idx] == -1) return;
            total += (long long)vals[idx] * depth;
            self(self, 2 * idx + 1, depth + 1);
            self(self, 2 * idx + 2, depth + 1);
        };
        dfs(dfs, 0, 1);
        return total;
    }
};

class Solution {
    private long total = 0;

    public long weightedSumOfTree(int[] vals) {
        total = 0;
        if (vals == null || vals.length == 0) return 0;
        dfs(0, 1, vals);
        return total;
    }

    private void dfs(int idx, int depth, int[] vals) {
        if (idx >= vals.length || vals[idx] == -1) return;
        total += (long)vals[idx] * depth;
        dfs(2 * idx + 1, depth + 1, vals);
        dfs(2 * idx + 2, depth + 1, vals);
    }
}

function weightedSumOfTree(rootVals) {
    if (!rootVals || rootVals.length === 0 || rootVals[0] === null) return 0;
    const n = rootVals.length;
    let total = 0;
    function dfs(idx, depth) {
        if (idx >= n || rootVals[idx] === null || rootVals[idx] === -1) return;
        total += rootVals[idx] * depth;
        dfs(2 * idx + 1, depth + 1);
        dfs(2 * idx + 2, depth + 1);
    }
    dfs(0, 1);
    return total;
}
